use std :: fmt ; use std :: path :: Path ; use std :: time :: Duration ; use colored :: Colorize ; use forge_api :: { Conversation , Environment , ForgeConfig , Metrics , Role , Usage , UserUsage } ; use forge_tracker :: VERSION ; use num_format :: { Locale , ToFormattedString } ; use crate :: display_constants :: markers ; use crate :: model :: ForgeCommandManager ; use std :: path :: PathBuf ; use forge_api :: { Environment , EventValue } ; use pretty_assertions :: assert_eq ; use fake :: { Fake , Faker } ; use forge_api :: Metrics ; use forge_domain :: { FileOperation , ToolKind } ; use chrono :: Utc ; use forge_api :: ConversationId ; use forge_domain :: { FileOperation , ToolKind } ; use super :: { Conversation , Metrics } ; use chrono :: Utc ; use forge_api :: ConversationId ; use super :: { Conversation , Metrics } ; use chrono :: Utc ; use forge_api :: { Context , ContextMessage , ConversationId , Role } ; use super :: { Conversation , Metrics } ; use super :: Info ; use forge_api :: Metrics ; use forge_domain :: { FileOperation , ToolKind } ; use forge_api :: Metrics ; use forge_domain :: { FileOperation , ToolKind } ; impl Info { pub fn new () -> Self { Info { sections : Vec :: new () } } # [doc = " Returns a reference to the sections"] pub fn sections (& self) -> & [Section] { & self . sections } # [doc = " Adds a section title to the info display."] # [doc = ""] # [doc = " Section titles are displayed in UPPERCASE, bold, and dimmed. They group"] # [doc = " related key-value pairs that follow."] # [doc = ""] # [doc = " # Convention"] # [doc = " - Always use UPPERCASE for section titles"] # [doc = " - Keep titles concise (e.g., \"CONFIGURATION\", \"METRICS\", \"USER\")"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " let info = Info::new()"] # [doc = "     .add_title(\"ENVIRONMENT\")  // Correct: UPPERCASE"] # [doc = "     .add_key_value(\"Path\", \"/home/user\");"] # [doc = " ```"] pub fn add_title (mut self , title : impl ToString) -> Self { self . sections . push (Section :: Title (title . to_string ())) ; self } # [doc = " Adds a standalone value without a key (displayed as a bullet point)."] # [doc = ""] # [doc = " Values without keys are displayed with a bullet point (⦿) and indented."] # [doc = " Use this for lists or grouped items under a section."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " let info = Info::new()"] # [doc = "     .add_title(\"AVAILABLE TOOLS\")"] # [doc = "     .add_value(\"read\")"] # [doc = "     .add_value(\"write\")"] # [doc = "     .add_value(\"shell\");"] # [doc = " ```"] # [doc = ""] # [doc = " Output:"] # [doc = " ```text"] # [doc = " AVAILABLE TOOLS"] # [doc = "   ⦿ read"] # [doc = "   ⦿ write"] # [doc = "   ⦿ shell"] # [doc = " ```"] pub fn add_value (self , value : impl IntoInfoValue) -> Self { self . add_item (None :: < String > , value) } # [doc = " Adds a key without a value (displays as a label)."] # [doc = ""] # [doc = " This is typically used for labels or empty fields. The key is displayed"] # [doc = " without any value following it."] # [doc = ""] # [doc = " # Convention"] # [doc = " - Use **Title Case** for keys (same as"] # [doc = "   [`add_key_value`](Self::add_key_value))"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " let info = Info::new()"] # [doc = "     .add_title(\"EMPTY FIELDS\")"] # [doc = "     .add_key(\"API Key\");  // Shows just \"api key\" without a value"] # [doc = " ```"] pub fn add_key (self , key : impl ToString) -> Self { self . add_key_value (key , None :: < String >) } # [doc = " Adds a key-value pair to the info display."] # [doc = ""] # [doc = " The key is displayed in green bold, and the value follows it. Keys are"] # [doc = " automatically aligned within each section."] # [doc = ""] # [doc = " # Conventions"] # [doc = ""] # [doc = " ## Keys"] # [doc = " - Use **Title Case** (e.g., \"Default Model\", \"API Key\", \"Working"] # [doc = "   Directory\")"] # [doc = " - Be descriptive but concise"] # [doc = " - Avoid abbreviations unless widely known"] # [doc = ""] # [doc = " ## Values"] # [doc = " - Use the constants from [`crate::display_constants`] for special"] # [doc = "   values:"] # [doc = "   - `placeholders::EMPTY` - empty value (`[empty]`)"] # [doc = "   - `status::ENABLED` - enabled/configured (`[enabled]`)"] # [doc = "   - `status::DISABLED` - disabled (`[disabled]`)"] # [doc = " - For actual values: Use the raw value (e.g., \"gpt-4\", \"/home/user\")"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " use crate::display_constants::status;"] # [doc = ""] # [doc = " let info = Info::new()"] # [doc = "     .add_title(\"CONFIGURATION\")"] # [doc = "     // Correct: Raw value for actual data"] # [doc = "     .add_key_value(\"Default Model\", \"gpt-4\")"] # [doc = "     // Correct: Status constant for status values"] # [doc = "     .add_key_value(\"Provider Status\", status::ENABLED)"] # [doc = "     // Correct: Raw value for actual data"] # [doc = "     .add_key_value(\"API URL\", \"https://api.example.com\");"] # [doc = " ```"] # [doc = ""] # [doc = " # Incorrect Usage"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " // ❌ Wrong: lowercase key"] # [doc = " .add_key_value(\"model\", \"gpt-4\")"] # [doc = ""] # [doc = " // ❌ Wrong: raw string instead of constant"] # [doc = " .add_key_value(\"Status\", \"[enabled]\")"] # [doc = ""] # [doc = " // ✅ Correct: Title Case key with constant"] # [doc = " .add_key_value(\"Status\", status::ENABLED)"] # [doc = " ```"] pub fn add_key_value (self , key : impl ToString , value : impl IntoInfoValue) -> Self { let key_str = key . to_string () ; let normalized_key = key_str . to_lowercase () ; self . add_item (Some (normalized_key) , value) } fn add_item (mut self , key : Option < impl ToString > , value : impl IntoInfoValue) -> Self { self . sections . push (Section :: Items (key . map (| a | a . to_string ()) , value . into_value () . unwrap_or (markers :: EMPTY . to_string ()) ,)) ; self } pub fn extend (mut self , other : impl Into < Info >) -> Self { self . sections . extend (other . into () . sections) ; self } }